package main

import (
	"fmt"
	"strings"
)

const target = "CODEFORCES"

func main() {
	var s string
	fmt.Scanln(&s)

	if check(s) {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

func check(s string) bool {
	if len(s) < len(target) {
		return false
	}
	if strings.HasPrefix(s, target) || strings.HasSuffix(s, target) {
		return true
	}
	for i := 1; i < len(target); i++ {
		prefix := target[:i]
		suffix := target[i:]
		if strings.HasPrefix(s, prefix) && strings.HasSuffix(s, suffix) {
			return true
		}
	}
	return false
}

